INSERT OR REPLACE INTO subject VALUES ('site:c-02cefa1fcdc4', 'c-02cefa1fcdc4', 'place', 'cyrenaica', 'Qadhdhafi speech at rally marking the 18th anniversary of the evacuation of British troops from the base', 32.0761, 23.9614, 12, 1988, 1988, 'documented', '{"uid":"site:c-02cefa1fcdc4","id":"c-02cefa1fcdc4","class":"place","region":"cyrenaica","order":202,"set":"sites","layer":"landmark","level":"documented","y0":1988,"y1":1988,"name":"Qadhdhafi speech at rally marking the 18th anniversary of the evacuation of British troops from the base","lat":32.0761,"lon":23.9614,"r":12,"pos":"town","posSrc":{"t":"Wikipedia: Tobruk","u":"https://en.wikipedia.org/wiki/Tobruk"},"period":"28 March 1988","relevance":"Qadhdhafi speech at rally marking the 18th anniversary of the evacuation of British troops from the base; he announced withdrawal of all Libyan military forces from the…","text":"Qadhdhafi speech at rally marking the 18th anniversary of the evacuation of British troops from the base; he announced withdrawal of all Libyan military forces from the Libyan-Egyptian border. This rests on one document: AL-QADHDHAFI ON ''LIBERATION,'' EGYPT, FREEDOM (28 March 1988). No second source is held for it. Mapped at the centre of Tobruk: the document names the town, not the site."}');
INSERT OR REPLACE INTO subject VALUES ('site:c-456563cb66cc', 'c-456563cb66cc', 'place', 'cyrenaica', 'Tubruq SA-6 SAM Support Facility', 32.0761, 23.9614, 12, NULL, NULL, 'documented', '{"uid":"site:c-456563cb66cc","id":"c-456563cb66cc","class":"place","region":"cyrenaica","order":203,"set":"sites","layer":"military","level":"documented","name":"Tubruq SA-6 SAM Support Facility","lat":32.0761,"lon":23.9614,"r":12,"pos":"town","posSrc":{"t":"Wikipedia: Tobruk","u":"https://en.wikipedia.org/wiki/Tobruk"},"period":"Date not given","relevance":"Housed a tank battalion with at least 30 medium tanks, normally parked in sheds, dispersed within the facility in 1983.","text":"Housed a tank battalion with at least 30 medium tanks, normally parked in sheds, dispersed within the facility in 1983. The same place appears in 3 separate readings, also described as: Tubruq Airfield; Tubrug (Tobruk) SA-6 SAM Support Facility South. 3 documents mention it (all from one publisher, cia.gov). Mapped at the centre of Tobruk: the document names the town, not the site."}');
