INSERT OR REPLACE INTO subject VALUES ('site:c-2e05e9199930', 'c-2e05e9199930', 'place', 'sirte', 'Sarir-to-Surt pipeline', 31.205, 16.5886, 12, NULL, NULL, 'documented', '{"uid":"site:c-2e05e9199930","id":"c-2e05e9199930","class":"place","region":"sirte","order":265,"set":"sites","layer":"landmark","level":"documented","name":"Sarir-to-Surt pipeline","lat":31.205,"lon":16.5886,"r":12,"pos":"town","posSrc":{"t":"Wikipedia: Sirte","u":"https://en.wikipedia.org/wiki/Sirte"},"period":"Date not given","relevance":"Pipeline under construction as part of the Great Manmade River Project, shown on Figure 1.","text":"Pipeline under construction as part of the Great Manmade River Project, shown on Figure 1. This rests on one document: LIBYA''S GREAT MANMADE RIVER PROJECT: PLANS AND REALITIES. No second source is held for it. Mapped at the centre of Sirte: the document names the town, not the site."}');
