INSERT OR REPLACE INTO subject VALUES ('area:npic-ghat-airfield-north', 'npic-ghat-airfield-north', 'area', 'tripoli', 'Ghat airfield (north)', 25.1325, 10.14889, 0.8, NULL, NULL, NULL, '{"uid":"area:npic-ghat-airfield-north","id":"npic-ghat-airfield-north","class":"area","region":"tripoli","order":452,"set":"areas","hasSources":true,"name":"Ghat airfield (north)","kind":"military","sym":"airfield","lat":25.1325,"lon":10.14889,"r":0.8,"far":true,"summary":"A south-western airfield where Foxbat interceptors were first seen in 1982.","history":"Jan 1982: Foxbat are identified for the first time at this airfield.","era":"Documented in declassified CIA imagery reports dated 1982, so it was in Gaddafi-era use then.","today":"Not described in the documents used.","uncertain":"Coordinates are those printed in the CIA briefing boards. The reports date only what the imagery showed; when the site was built, how long it stayed in use and who used it after 2011 are not documented here.","documented":"Seen in US imagery in Jan 1982; later use not documented","distance_from_tripoli_km":912}');
INSERT OR REPLACE INTO subject VALUES ('area:lm-bab-darghouth', 'lm-bab-darghouth', 'area', 'tripoli', 'Bab Darghouth', 32.8991, 13.1773, 0.1, NULL, NULL, NULL, '{"uid":"area:lm-bab-darghouth","id":"lm-bab-darghouth","class":"area","region":"tripoli","order":453,"set":"areas","hasSources":true,"name":"Bab Darghouth","ar":"باب درغوث","aliases":["Darghut Gate","Bab Dargut"],"kind":"landmark","lat":32.8991,"lon":13.1773,"r":0.1,"summary":"A city gate of the Old City named after Darghut (Turgut Reis), near the Sidi Darghut mosque. The OpenStreetMap extract tags it as a city gate in the Old City. The sources seen give no history for this gate and no events during 1969-2011.","today":"Not described in the sources seen.","uncertain":"History and present state are not documented in the sources seen; only its map position is known."}');
INSERT OR REPLACE INTO subject VALUES ('area:lm-7-october-stadium', 'lm-7-october-stadium', 'area', 'tripoli', '7 October Stadium (Municipal Stadium)', 32.8883, 13.1652, 0.2, NULL, NULL, NULL, '{"uid":"area:lm-7-october-stadium","id":"lm-7-october-stadium","class":"area","region":"tripoli","order":454,"set":"areas","hasSources":true,"name":"7 October Stadium (Municipal Stadium)","aliases":["Tripoli Municipal Stadium"],"kind":"landmark","lat":32.8883,"lon":13.1652,"r":0.2,"summary":"A small football ground in central Tripoli built in 1939. Built in 1939 as the Municipal Stadium; until the June 11 Stadium opened in the 1970s it was the only football stadium in Tripoli. Capacity 5,000.","today":"Used as a training ground for Al-Ittihad Club.","uncertain":"Gaddafi-era events not documented."}');
INSERT OR REPLACE INTO subject VALUES ('area:lb-ministry-of-interior', 'lb-ministry-of-interior', 'area', 'tripoli', 'Ministry of Interior', 32.89431, 13.17962, 0.3, NULL, NULL, NULL, '{"uid":"area:lb-ministry-of-interior","id":"lb-ministry-of-interior","class":"area","region":"tripoli","order":455,"set":"areas","hasSources":true,"name":"Ministry of Interior","ar":"وزارة الداخلية","kind":"government","lat":32.89431,"lon":13.17962,"r":0.3,"summary":"Government ministry office in Tripoli, mapped at this location.","today":"Under the Jamahiriya the cabinet was the General People''s Committee, whose members were called secretaries rather than ministers; the ministry names here are the post-2011 usage.","uncertain":"Only the mapped position is documented; the ministry may have occupied other buildings under Gaddafi, and several ministries have more than one mapped office."}');
