INSERT OR REPLACE INTO subject VALUES ('k-680e1ce9a23e', 'k-680e1ce9a23e', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-680e1ce9a23e","id":"k-680e1ce9a23e","class":"connection","region":"tripoli","order":652,"set":"connections","hasSources":true,"a":"maktab","b":"abusalim","kind":"transfer","why":"Maktab al-Nasser held prisoners, many of whom were later moved on to Abu Salim; dates unverified.","year":null,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-01acb434537c', 'k-01acb434537c', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-01acb434537c","id":"k-01acb434537c","class":"connection","region":"tripoli","order":653,"set":"connections","hasSources":true,"a":"bab","b":"abusalim","kind":"attack","why":"After the 8 May 1984 attack on Bab al-Aziziya, most of those arrested were believed held at Abu Salim, whose first prisoners arrived in 1984.","year":1984,"confidence":"documented"}');
INSERT OR REPLACE INTO subject VALUES ('k-091ced5bd260', 'k-091ced5bd260', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-091ced5bd260","id":"k-091ced5bd260","class":"connection","region":"tripoli","order":654,"set":"connections","hasSources":true,"a":"ainzara","b":"abusalim","kind":"same-unit","why":"The Internal Security Agency held full control of both Ain Zara and Abu Salim prisons, including detainees kept past their sentences.","year":2009,"confidence":"documented"}');
INSERT OR REPLACE INTO subject VALUES ('k-c1b501ef3e51', 'k-c1b501ef3e51', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-c1b501ef3e51","id":"k-c1b501ef3e51","class":"connection","region":"tripoli","order":655,"set":"connections","hasSources":true,"a":"hadba","b":"mk-abusalim","kind":"context","why":"Seventy-seven detainees tied to the 1996 Abu Salim killings were being held at al-Hadba in 2017 before their move to Ain Zara.","year":2017,"confidence":"documented"}');
INSERT OR REPLACE INTO subject VALUES ('k-7589ab7a87e4', 'k-7589ab7a87e4', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-7589ab7a87e4","id":"k-7589ab7a87e4","class":"connection","region":"tripoli","order":656,"set":"connections","hasSources":true,"a":"ainzara","b":"mk-abusalim","kind":"context","why":"The 77 detainees linked to the 1996 Abu Salim killings were confirmed at Ain Zara in November 2017.","year":2017,"confidence":"documented"}');
INSERT OR REPLACE INTO subject VALUES ('k-5a6640e8c1c5', 'k-5a6640e8c1c5', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-5a6640e8c1c5","id":"k-5a6640e8c1c5","class":"connection","region":"tripoli","order":657,"set":"connections","hasSources":true,"a":"abusalim","b":"mk-abusalim","kind":"same-place","why":"The June 1996 massacre happened inside Abu Salim prison, where about 1,200 prisoners were reportedly killed.","year":1996,"confidence":"documented"}');
INSERT OR REPLACE INTO subject VALUES ('k-6d9bd9030128', 'k-6d9bd9030128', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-6d9bd9030128","id":"k-6d9bd9030128","class":"connection","region":"tripoli","order":658,"set":"connections","hasSources":true,"a":"jdeida","b":"mk-feb2011","kind":"context","why":"After the February 2011 protests, HRW feared Tripoli detainees were being held at Jdeida, Ain Zara and Abu Salim prisons.","year":2011,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-b9acdcaef3b0', 'k-b9acdcaef3b0', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-b9acdcaef3b0","id":"k-b9acdcaef3b0","class":"connection","region":"tripoli","order":659,"set":"connections","hasSources":true,"a":"ainzara","b":"mk-feb2011","kind":"context","why":"HRW feared protesters seized after the 20 February 2011 shootings were held at Ain Zara among other prisons.","year":2011,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-bdfc558b47db', 'k-bdfc558b47db', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-bdfc558b47db","id":"k-bdfc558b47db","class":"connection","region":"tripoli","order":660,"set":"connections","hasSources":true,"a":"abusalim","b":"mk-feb2011","kind":"casualties","why":"HRW heard that at least 50 bodies lay in the Abu Salim hospital morgue after the 21-22 February 2011 shootings; HRW also feared detainees were held at Abu Salim prison.","year":2011,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-6316ff1df987', 'k-6316ff1df987', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-6316ff1df987","id":"k-6316ff1df987","class":"connection","region":"tripoli","order":661,"set":"connections","hasSources":true,"a":"jdeida","b":"furnaj","kind":"same-place","why":"Amnesty placed al-Jdayda prison at al-Farnaj outside Tripoli, holding 24 students sentenced in 1995.","year":1995,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-541c7fa7c66e', 'k-541c7fa7c66e', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-541c7fa7c66e","id":"k-541c7fa7c66e","class":"connection","region":"tripoli","order":662,"set":"connections","hasSources":true,"a":"jdeida","b":"lb-ministry-of-justice","kind":"same-unit","why":"Jdeida prison was run by the General People''s Committee of Justice, the Jamahiriya-era justice authority, when Amnesty visited in May 2009.","year":2009,"confidence":"documented"}');
INSERT OR REPLACE INTO subject VALUES ('k-622557170e50', 'k-622557170e50', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-622557170e50","id":"k-622557170e50","class":"connection","region":"tripoli","order":663,"set":"connections","hasSources":true,"a":"abusalim","b":"lb-abu-salim-prison","kind":"same-place","why":"The curated Abu Salim site and the area profile describe the same prison, completed in 1984.","year":1984,"confidence":"documented"}');
