INSERT OR REPLACE INTO subject VALUES ('k-8332f8eb8ac2', 'k-8332f8eb8ac2', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-8332f8eb8ac2","id":"k-8332f8eb8ac2","class":"connection","region":"tripoli","order":665,"set":"connections","hasSources":true,"a":"lb-abu-salim-prison","b":"central-security","kind":"control","why":"In 2017 Abu Salim prison was held by the Central Security/Abu Salim armed group, per the UN.","year":2017,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-e89ab73d7957', 'k-e89ab73d7957', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-e89ab73d7957","id":"k-e89ab73d7957","class":"connection","region":"tripoli","order":666,"set":"connections","hasSources":true,"a":"lb-tripoli-supreme-court","b":"mk-abusalim","kind":"context","why":"On 2 May 2021 Libya''s Supreme Court ruled the 1996 Abu Salim massacre a genocide and sent the case back to a lower court.","year":2021,"confidence":"reported"}');
INSERT OR REPLACE INTO subject VALUES ('k-5346b9cbff15', 'k-5346b9cbff15', 'connection', 'tripoli', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"uid":"k-5346b9cbff15","id":"k-5346b9cbff15","class":"connection","region":"tripoli","order":667,"set":"connections","hasSources":true,"a":"hadba","b":"mk-feb2011","kind":"context","why":"Senior Gaddafi-era figures including Saadi Gaddafi were held at al-Hadba prison during the post-2011 trial of the 2011 crackdown officials.","year":2015,"confidence":"reported"}');
