INSERT OR REPLACE INTO claim VALUES ('c-1144ba15ef42', 'site:as-benashour', 'account', 'src-fea0ddc0b4e1', '1986 United States bombing of Libya, Wikipedia', 4, NULL, NULL, 'documented', '{"before":"NATO E-3A AWACS aircraft flying out of Trapani air base in Italy provided airborne surveillance. === United States Navy === America was on station in the Gulf of Sidra, but Coral Sea was preparing to leave the Mediterranean, and made a high speed run from Naples through the Strait of Messina.","text":"America''s air group would strike targets in downtown Benghazi and provide fighter and suppression support for the USAF bombers, while Coral Sea''s planes would strike the Benina airfield outside Benghazi and provide fighter and suppression support for the Navy bombers.","after":"About 01:00 America launched six A-6E TRAM Intruder strike aircraft with Mark 82 bombs against the Jamahiriyah Guard barracks and six A-7 Corsair II strike support aircraft.","from":"1986 United States bombing of Libya (Wikipedia)","date":null}', 'stored', 'C', 1, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
