INSERT OR REPLACE INTO claim VALUES ('c-853f5cb7660f', 'site:as-benashour', 'account', 'src-09ffb03f7fce', 'Tripoli, Wikipedia (1986 raid toll)', 7, NULL, NULL, 'documented', '{"before":"On 15 April 1986, U.S.","text":"President Ronald Reagan ordered major bombing raids, dubbed Operation El Dorado Canyon, against Tripoli and Benghazi, killing 45 Libyan military and government personnel as well as 15 civilians.","after":"This strike followed US interception of telex messages from Libya''s East Berlin embassy suggesting the involvement of Libyan leader Muammar Gaddafi in a bomb explosion on 5 April in West Berlin''s La Belle discothèque, a nightclub frequented by US servicemen.","from":"Tripoli, Libya (Wikipedia)","date":null}', 'stored', 'C', 1, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
