INSERT OR REPLACE INTO claim VALUES ('c-ebef2c573bed', 'site:bt-1984-bab', 'account', 'src-734282d3c805', 'CIA reading room: CIA: Libyan opposition groups, much sound, little fury (May 1987)', 9, NULL, NULL, 'documented', '{"before":"In April 1984 the NFSL had infiltrated into Libya three commando teams totaling about 30 men.","text":"At least half of this group was lost in the gunbattle with security forces in May 1984, including the founder and leader of the Salvation Forces, Ahmad Ahwas.","after":"Any survivors al- most certainly fled to avoid being discovered in the broad security sweeps that followed.","from":"LIBYAN OPPOSITION GROUPS: MUCH SOUND, LITTLE FURY","date":"1987-05-01"}', 'stored', 'B', 1, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
