INSERT OR REPLACE INTO claim VALUES ('c-6cb2fa215c03', 'site:mk-riots', 'account', 'src-01e7b56d38de', '1945 anti-Jewish riots in Tripolitania, Wikipedia', 0, NULL, NULL, 'documented', '{"before":"The 1945 anti-Jewish riots in Tripolitania were the most violent riots against Jews in North Africa in the 20th century.","text":"From November 5 to November 7, 1945, more than 140 Jews were killed and many more injured in a pogrom in Tripolitania, then under British military occupation.","after":"38 Jews were killed in Tripoli from where the riots spread.","from":"1945 anti-Jewish riots in Tripolitania (Wikipedia)","date":null}', 'stored', 'C', 2, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
