INSERT OR REPLACE INTO claim VALUES ('c-849bfad88647', 'site:bt-2014-airport', 'account', 'src-34a3cd77af08', 'Tripoli International Airport, Wikipedia', 0, NULL, NULL, 'documented', '{"before":"It was expected to be completed in 2024, however due to Libya failing to keep up with payments the Italian firms delayed construction in October 2024 before the project was transferred to a Libyan contractor.","text":"The first asphalt layer of the runway was reportedly laid in September 2025. == Airlines and destinations == As of July 2014, all passenger flights into Tripoli use Mitiga International Airport; all scheduled cargo operations into Tripoli International Airport have also ceased. == Accidents and incidents == On 9 May 1944, a Douglas Dakota III (KG548) of the RAF crashed and burned on takeoff during its delivery flight when the undercarriage retracted.","after":"It is unknown if anyone died.","from":"Tripoli International Airport (Wikipedia)","date":null}', 'stored', 'C', 2, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
INSERT OR REPLACE INTO claim VALUES ('c-8cb730cf0989', 'site:bt-2018', 'account', 'src-972b13eab7ec', 'Battle of Tripoli (2018), Wikipedia', 0, NULL, NULL, 'documented', '{"before":"","text":"The Battle of Tripoli was a series of clashes in Tripoli, Libya from 27 August to 25 September 2018 during the Second Libyan Civil War.","after":"It was fought between several militias and was ended by a ceasefire. == Prelude == Clashes between militias broke out in Tripoli from 26 to 27 August 2018, touching off renewed fighting in the city after 18 months of relative calm.","from":"Battle of Tripoli (2018) (Wikipedia)","date":null}', 'stored', 'C', 2, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
INSERT OR REPLACE INTO claim VALUES ('c-6d65ec523b80', 'site:bt-2025', 'account', 'src-6f3fe3118760', '2025 Tripoli clashes, Wikipedia', 0, NULL, NULL, 'documented', '{"before":"","text":"On 12 May 2025, clashes broke out in Tripoli, Libya, between the 444th Infantry Brigade and the Stability Support Apparatus (SSA).","after":"The fighting began after SSA commander Abdel Ghani al-Kikli was assassinated.","from":"2025 Tripoli clashes (Wikipedia)","date":null}', 'stored', 'C', 2, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
