INSERT OR REPLACE INTO claim VALUES ('c-db913e28f0b7', 'site:mk-sadr-1978', 'account', 'src-ee453f1396ea', 'FBIS, 7 Dec 1979', 0, NULL, NULL, 'suspected', '{"before":"The imam, Shaykh Muhammad Sha''ta Ya''qub and ''Abbas Badr were executed by Lieutenant Faraj Bughaliyah and four under-officers who misinterpreted an order, AL-MUHARRIR said, citing a reliable Arab source.","text":"The newspaper, organ of the Socialist Union of Popular Forces, said Imam as-Sadr and his companions were executed on a firing range near Janzur, 30 kms (20 miles) from [fripoli.","after":"Ve.","from":"FBIS Daily Report: Middle East & N. Africa, Vol. V No. 237, 7 December 1979","date":"1979-12-07"}', 'stored', 'B', 6, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
INSERT OR REPLACE INTO claim VALUES ('c-df3678a49c7c', 'site:mk-suwani-1982', 'account', 'src-7d2d2a61b7a2', 'JPRS Near East/North Africa Report No. 2701', 0, NULL, NULL, 'testimony', '{"before":"OCR text: errors are likely.","text":"LIBYA EXECUTIONS FOLLOW UNREPORTED COUP ATTEMPT Cairo AL-JUMHURIYAH in Arabic 18 Dec 82 p l [Article by the Rome correspondent for AL-JUMHURIYAH: \"Execution of Four Officers in the Libyan Army Who Attempted a Coup\"] [Text] Libyan president Mu''ammar al-Qadhdhafi has executed four of the officers who staged an undisclosed coup attempt.","after":"The executions took place in a villa belonging to Idris al-Sanusi, former king of Libya, at the Suwani bin Yadim cattle farm located 20 miles south of the city of Tripoli, which Libyan intelligence uses for interrogation and torture purposes.","from":"Near East/North Africa Report No. 2701","date":"1983-02-03"}', 'stored', 'B', 3, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
INSERT OR REPLACE INTO claim VALUES ('c-708b3fc08854', 'site:mk-suwani-1982', 'account', 'src-46ccbe68b66a', 'FBIS, 18 Nov 1982: 100 arrested in foiled attack on al-Qadhdhafi (AFP)', 1, NULL, NULL, 'testimony', '{"before":"The brother leader called on the conferees to safeguard and maintain the conference annually and to achieve further positive results in the interests of the Arab citizen.","text":"100 ARRESTED IN FOILED ATTACK ON AL-QADHDHAFI NC171047 Paris AFP in English 0945 GMT 17 Nov 82 [Text] Paris, Nov 17 (AFP) -- Some 100 Libyan military and security officers were reportedly arrested early this month as they were preparing to attack a plane carrying Libyan leader Mu''ammar al-Qadhdhafi, a London-based Arabic language news- paper reported today.","after":"The paper, ASH-SHARQ A’ AWSAT, said the attack, planned for November 4 when Colonel al-Qadhdhafi was scheduled to return from a visit to Yugoslavia, was foiled when one of the officers alerted loyalist security forces who captured the plotters hours before the plane was due to arrive.","from":"FBIS Daily Report: Middle East & Africa, Vol. V No. 223, 18 November 1982","date":"1982-11-18"}', 'stored', 'B', 3, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
