INSERT OR REPLACE INTO claim VALUES ('c-e718ae966f8b', 'site:mk-hang-1984-agri', 'account', 'src-c65dce5552ca', 'CIA reading room: Washington Post, 23 Apr 1984: Hangings in Tripoli focus attention on Libyan dissent', 1, NULL, NULL, 'testimony', '{"before":"In‘a visit today to the sprawling campus, which has an eerie resemblance to American university campuses plastered with posters in the 1960s, questions about the previous week’s executions drew icy stares and a few reluctant confirmations.","text":"One was from a fourth-year engineering student who sat on a stone bench in the Agriculture Square where the second gallows stood.","after":"The sec- ond student who was executed apparently had about it,” the engineering student said.","from":"HANGINGS IN TRIPOLI FOCUS ATENTION ON LIBYAN DISSENT","date":"1984-04-23"}', 'stored', 'B', 3, 'owner (by statement)', '2026-11-16', 'migrated from public/data. The original review was never recorded; on 16 Nov 2026 the owner stated in chat that these claims are good. That is a statement, not a per-claim review, and the date is the date of the statement.');
